// Normalize and validate input
const input = $input.first().json || {};

const client_id = Number(
  input.client_id ??
  input.clientId ??
  input.user_id ??
  input.userId ??
  input.user?.id ??
  null
);

if (!client_id || !Number.isFinite(client_id)) {
  return [{
    ok: false,
    error: 'Missing or invalid client_id. Please authenticate the user first.',
    tool: 'get_transactions'
  }];
}

return [{ client_id }];

// Return only the fields needed by the assistant
const input = $('Normalize Input').item.json;
const rows = $input.all().map((item) => item.json).filter(Boolean);

let txList = [];
if (rows.length === 1 && Array.isArray(rows[0])) {
  txList = rows[0];
} else if (rows.length === 1 && Array.isArray(rows[0]?.data)) {
  txList = rows[0].data;
} else {
  txList = rows;
}

const latest = txList
  .filter((tx) => tx && typeof tx === 'object')
  .sort((a, b) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime())
  .slice(0, 5)
  .map((tx) => ({
    id: tx.id ?? null,
    createdAt: tx.createdAt ?? null,
    type: tx.type ?? null,
    status: tx.status ?? null,
    psp: tx.psp ?? null,
    comment: tx.comment ?? null
  }));

const summary = {
  by_type: {},
  by_status: {}
};

for (const tx of latest) {
  const typeKey = String(tx.type || 'unknown').toLowerCase();
  const statusKey = String(tx.status || 'unknown').toLowerCase();
  summary.by_type[typeKey] = (summary.by_type[typeKey] || 0) + 1;
  summary.by_status[statusKey] = (summary.by_status[statusKey] || 0) + 1;
}

return [{
  ok: true,
  client_id: input.client_id,
  transactions_count: latest.length,
  transactions: latest,
  summary
}];
